  ],
  "claims": [
    {
      "claim": "Posaconazole, a large lipophilic azole with solubility-limited absorption, had absolute oral bioavailability of 42–56% in fasted humans and 85–87% in fed humans; all values are well above the 20% threshold.",
      "card_ids": ["C02", "C03", "C09", "C13"]
    },
    {
      "claim": "UDCA, a steroid carboxylic acid structurally closest to the query's steroid-acid core, had systemic availability of 78–87% after oral dosing in cirrhotic patients.",
      "card_ids": ["C18"]
    },
    {
      "claim": "BI 425809, given as a 25 mg tablet in fasted healthy subjects, had absolute bioavailability of 71.6% (90% CI 64.3–79.9), supporting high oral F for a challenging lipophilic oral drug.",
      "card_ids": ["C01", "C04", "C15", "C21"]
    },
    {
      "claim": "Cilomilast, an acid-containing oral drug, had mean absolute bioavailability of 96% (range 92–102%) in fasted volunteers.",
      "card_ids": ["C12"]
    },
    {
      "claim": "KNI-272, a large peptidomimetic, had absolute bioavailability of 36.4% post-prandially, still above the 20% threshold.",
      "card_ids": ["C05"]
    },
    {
      "claim": "Additional human oral F values in the visible L1 set are also above 20%: perindopril 66–95% fasted, atazanavir >90% fed, pentazocine ~0.68–0.70 in cirrhosis, and phenoxymethylpenicillin 35.9–82.6% in children.",
      "card_ids": ["C19", "C11", "C20", "C07", "C16", "C06", "C08", "C14", "C17"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C01", "C02", "C03", "C05", "C09", "C11", "C12", "C13", "C16", "C18", "C19", "C20"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "No prandial state is specified for the query; fed/fasted can change F substantially, as seen with posaconazole.",
    "No formulation, IV-comparator, or human PK data are available for the query itself.",
    "Physicochemical liabilities (MW 730, logP 8.62, TPSA 125, zwitterionic character) may limit absorption, but no affirmative low-F experimental evidence is present.",
    "Transfer from the visible contexts is qualitative; no exact structural match is available."
  ],
  "decision_summary": "All transferable L1 records report F values above 20% (range approximately 36–96%), including structurally relevant azole and steroid-acid analogs. The physicochemical low prior is not affirmative evidence for F < 20%, so the better-supported prediction is high, with moderate confidence due to transfer uncertainty."
}

